from collections import deque

def find_components(grid, target_val):
    n, m = len(grid), len(grid[0])
    visited = set()
    components = []

    for i in range(n):
        for j in range(m):
            if grid[i][j] == target_val and (i, j) not in visited:
                comp = []
                queue = deque([(i, j)])
                visited.add((i, j))
                while queue:
                    r, c = queue.popleft()
                    comp.append((r, c, grid[r][c]))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            if grid[nr][nc] == target_val and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))
                components.append(comp)
    return components

